import React, { useState, useEffect, useRef } from 'react';
import { CContainer } from '@coreui/react';
import { ArrowDownTrayIcon, ArrowRightIcon, StarIcon } from '@heroicons/react/24/solid';
import CustomButton from './CustomButton';
import CountUp from './ui/CountUp';
import styles from '../css/TopFold.module.css';

const roles = ['Developer', 'Designer'];

const stats = [
  { value: 9, suffix: '+', label: 'Years of experience' },
  { value: 99, suffix: '+', label: 'Projects completed' },
  { value: 35, suffix: '+', label: 'Happy clients' },
];

const stack = [
  'React', 'Next.js', 'JavaScript', 'HTML5', 'CSS3', 'Bootstrap',
  'WordPress', 'MVC.NET', 'Contentful', 'Adobe Creative Cloud', 'UI/UX Design', 'Responsive Web',
];

function useTypewriter(words) {
  const [index, setIndex] = useState(0);
  const [text, setText] = useState('');
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    const full = words[index];
    let delay = deleting ? 70 : 120;
    if (!deleting && text === full) delay = 2000;

    const t = setTimeout(() => {
      if (!deleting && text === full) {
        setDeleting(true);
      } else if (deleting && text === '') {
        setDeleting(false);
        setIndex((i) => (i + 1) % words.length);
      } else {
        setText(deleting ? full.slice(0, text.length - 1) : full.slice(0, text.length + 1));
      }
    }, delay);

    return () => clearTimeout(t);
  }, [text, deleting, index, words]);

  return text;
}

function TopFold() {
  const typed = useTypewriter(roles);
  const heroRef = useRef(null);

  // Mouse-reactive glow + parallax (CSS vars only, no re-renders)
  useEffect(() => {
    const el = heroRef.current;
    if (!el || window.matchMedia('(pointer: coarse)').matches) return undefined;

    const onMove = (e) => {
      const r = el.getBoundingClientRect();
      const x = (e.clientX - r.left) / r.width - 0.5;
      const y = (e.clientY - r.top) / r.height - 0.5;
      el.style.setProperty('--px', x.toFixed(3));
      el.style.setProperty('--py', y.toFixed(3));
      el.style.setProperty('--gx', `${e.clientX - r.left}px`);
      el.style.setProperty('--gy', `${e.clientY - r.top}px`);
    };
    el.addEventListener('pointermove', onMove);
    return () => el.removeEventListener('pointermove', onMove);
  }, []);

  const openResume = () => {
    window.open(`${process.env.PUBLIC_URL}/resume.pdf`, '_blank');
  };

  const goToProjects = () => {
    document.getElementById('projects')?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <div className={styles.hero} ref={heroRef}>
      <div className="grid-bg" aria-hidden="true" />
      <div className={styles.glow} aria-hidden="true" />
      <div className={`${styles.orb} ${styles.orb1}`} aria-hidden="true" />
      <div className={`${styles.orb} ${styles.orb2}`} aria-hidden="true" />

      <CContainer className={styles.inner}>
        <div className={styles.grid}>
          {/* Left: intro copy */}
          <div className={styles.copy}>
            <p className={`reveal ${styles.status}`}>
              <span className={styles.statusDot} />
              Available for new opportunities
            </p>

            <h1 className={styles.title}>
              <span className={`reveal ${styles.hello}`} data-delay="1">
                Hi, I'm Christian —
              </span>
              <span className={`reveal ${styles.headline}`} data-delay="2">
                Creative{' '}
                <span className={styles.typeWrap}>
                  <span className="gradient-text">{typed}</span>
                  <span className={styles.caret} aria-hidden="true" />
                </span>
              </span>
            </h1>

            <p className={`reveal ${styles.body}`} data-delay="3">
              Front-end developer &amp; UI/UX designer from Cebu, Philippines. I turn complicated
              user-experience problems into fast, honest and beautifully simple interfaces.
            </p>

            <div className={`reveal ${styles.actions}`} data-delay="4">
              <CustomButton text="Download Resume" Icon={ArrowDownTrayIcon} onClick={openResume} />
              <CustomButton text="View my work" Icon={ArrowRightIcon} onClick={goToProjects} variant="ghost" />
            </div>

            <div className={`reveal ${styles.meta}`} data-delay="5">
              <span className="mono">{'// based in Cebu City, PH'}</span>
              <span className={styles.metaSep} />
              <span className="mono">React · UI/UX · WordPress</span>
            </div>
          </div>

          {/* Right: portrait */}
          <div className={`reveal ${styles.visual}`} data-anim="zoom" data-delay="2">
           {/* everything inside tilts toward the mouse; layers sit at different depths */}
           <div className={styles.tilt}>
            <div className={styles.ring} aria-hidden="true" />
            <div className={styles.ring2} aria-hidden="true" />

            {/* backdrop card — the photo breaks out of its top edge */}
            <div className={styles.card} aria-hidden="true">
              <span className={styles.cardGrid} />
              <span className={styles.cardGlow} />
              <span className={styles.sweep} />
              <span className={`${styles.cardMeta} ${styles.metaTL}`}>EST. 2017</span>
              <span className={`${styles.cardMeta} ${styles.metaBR}`}>CEBU · PH</span>
              <span className={styles.corner} />
            </div>

            <div className={styles.headGlow} aria-hidden="true" />

            {/* WebP (31 KB / 91 KB) for modern browsers, resized PNG fallback.
                `display: contents` keeps the <picture> wrapper out of the 3D chain. */}
            <picture className={styles.picture}>
              <source
                type="image/webp"
                srcSet={`${process.env.PUBLIC_URL}/images/christian-villareal-cutout-480.webp 480w, ${process.env.PUBLIC_URL}/images/christian-villareal-cutout-900.webp 900w`}
                sizes="(max-width: 640px) 82vw, 440px"
              />
              <img
                className={styles.photo}
                src={`${process.env.PUBLIC_URL}/images/christian-villareal-cutout-900.png`}
                alt="Christian Villareal"
                width={900}
                height={1050}
                fetchpriority="high"
                decoding="async"
                onError={(e) => {
                  // fall back to the original photo if the cutout is missing
                  e.currentTarget.onerror = null;
                  e.currentTarget.src = `${process.env.PUBLIC_URL}/images/christian-villareal.png`;
                }}
              />
            </picture>

            <div className={`${styles.chip} ${styles.chipCode}`}>
              <span className={styles.chipDot} />
              <code>&lt;Frontend /&gt;</code>
            </div>

            <div className={`${styles.chip} ${styles.review}`}>
              <div className={styles.stars} aria-label="5 star rating">
                {[0, 1, 2, 3, 4].map((i) => <StarIcon key={i} />)}
                <span>5.0</span>
              </div>
              <p className={styles.reviewTitle}>Amazing work!</p>
              <p className={styles.reviewText}>
                "Christian built a beautiful website that went beyond what we expected."
              </p>
            </div>
           </div>
          </div>
        </div>

        {/* Stats */}
        <div className={styles.stats}>
          {stats.map((s, i) => (
            <div key={s.label} className={`reveal card-glass spot ${styles.stat}`} data-delay={i + 1}>
              <span className={styles.statValue}>
                <CountUp end={s.value} suffix={s.suffix} />
              </span>
              <span className={styles.statLabel}>{s.label}</span>
            </div>
          ))}
        </div>
      </CContainer>

      {/* Tech stack marquee */}
      <div className={`reveal ${styles.marquee}`} data-delay="2" aria-label="Tech stack">
        <div className={styles.track}>
          {[...stack, ...stack].map((item, i) => (
            <span key={i} className={styles.tech} aria-hidden={i >= stack.length}>
              <span className={styles.techDot}>✦</span>
              {item}
            </span>
          ))}
        </div>
      </div>
    </div>
  );
}

export default TopFold;
