// src/components/Contact.jsx
import React, { useState } from 'react';
import { CContainer, CForm, CFormInput, CFormSelect, CFormTextarea } from '@coreui/react';
import SectionHeading from './ui/SectionHeading';
import styles from '../css/Contact.module.css';

function Contact() {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    option: '',
    message: ''
  });
  
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState({ type: '', message: '' });

  // Determine which API URL to use based on environment
  const API_URL = process.env.NODE_ENV === 'development' 
    ? 'http://localhost:3001'  // Local backend for development
    : 'https://portfolio-backend.onrender.com'; // Production backend on Render

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    if (submitStatus.message) setSubmitStatus({ type: '', message: '' });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validation
    if (!formData.firstName || !formData.lastName || !formData.email || !formData.option || !formData.message) {
      setSubmitStatus({ type: 'error', message: 'Please fill in all required fields.' });
      return;
    }

    if (!formData.email.includes('@')) {
      setSubmitStatus({ type: 'error', message: 'Please enter a valid email address.' });
      return;
    }

    setIsSubmitting(true);
    setSubmitStatus({ type: '', message: '' });

    try {
      console.log('Sending to:', `${API_URL}/api/contact`);
      console.log('Data:', formData);

      const response = await fetch(`${API_URL}/api/contact`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      const data = await response.json();

      if (response.ok) {
        setSubmitStatus({ 
          type: 'success', 
          message: 'Thank you! Your message has been sent successfully. I\'ll get back to you soon.' 
        });
        // Reset form
        setFormData({
          firstName: '',
          lastName: '',
          email: '',
          phone: '',
          option: '',
          message: ''
        });
      } else {
        throw new Error(data.error || 'Failed to send message');
      }
    } catch (error) {
      console.error('Error:', error);
      setSubmitStatus({ 
        type: 'error', 
        message: `Sorry, there was an error sending your message. ${error.message}` 
      });
    } finally {
      setIsSubmitting(false);
      
      // Auto-hide success message after 5 seconds
      setTimeout(() => {
        if (submitStatus.type === 'success') {
          setSubmitStatus({ type: '', message: '' });
        }
      }, 5000);
    }
  };

  const options = [
    { value: '', label: 'Choose a service' },
    { value: 'web-design', label: 'Web Design' },
    { value: 'web-development', label: 'Web Development' },
    { value: 'branding', label: 'Branding' },
    { value: 'ui-ux', label: 'UI/UX Design' },
    { value: 'other', label: 'Other' }
  ];

  const contactInfo = [
    {
      label: 'Phone',
      value: '+63 995 577 0369',
      href: 'tel:+639955770369',
      icon: <path d="M3 5.5C3 4.12 4.12 3 5.5 3h1.38c.6 0 1.12.4 1.26.98l.9 3.6a1.3 1.3 0 01-.37 1.25l-1.4 1.4a12.5 12.5 0 006.5 6.5l1.4-1.4c.33-.33.8-.46 1.25-.37l3.6.9c.58.14.98.66.98 1.26v1.38c0 1.38-1.12 2.5-2.5 2.5h-1C9.94 21 3 14.06 3 5.5v0z" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" />,
    },
    {
      label: 'Email',
      value: 'chanix.webdesigns@gmail.com',
      href: 'mailto:chanix.webdesigns@gmail.com',
      icon: <><rect x="3" y="5" width="18" height="14" rx="2.5" stroke="currentColor" strokeWidth="1.6" /><path d="M4 7l8 6 8-6" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" /></>,
    },
    {
      label: 'Location',
      value: 'Cebu City, Philippines',
      icon: <><path d="M12 21s-7-6.2-7-11.5a7 7 0 1114 0C19 14.8 12 21 12 21z" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" /><circle cx="12" cy="9.5" r="2.5" stroke="currentColor" strokeWidth="1.6" /></>,
    },
  ];

  return (
    <CContainer>
      <div className={styles.wrapper}>
        <div className="grid-bg" aria-hidden="true" />
        <div className={styles.glow} aria-hidden="true" />

        <div className={styles.grid}>
          <div className={styles.intro}>
            <SectionHeading
              index="07"
              eyebrow="Contact"
              title="Let's build something"
              highlight="great together."
              subtitle="I design and code beautifully simple things, and I love what I do. Tell me about your project — I usually reply within a day."
            />

            <ul className={styles.infoList}>
              {contactInfo.map((item, i) => {
                const Tag = item.href ? 'a' : 'div';
                return (
                  <li key={item.label} className="reveal" data-delay={i + 2}>
                    <Tag className={styles.infoItem} {...(item.href ? { href: item.href } : {})}>
                      <span className={styles.infoIcon}>
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true">{item.icon}</svg>
                      </span>
                      <span>
                        <span className={styles.infoLabel}>{item.label}</span>
                        <span className={styles.infoValue}>{item.value}</span>
                      </span>
                    </Tag>
                  </li>
                );
              })}
            </ul>
          </div>

          <div className={`reveal ${styles.formWrapper}`} data-anim="right" data-delay="2">
            {submitStatus.message && (
              <div className={`${styles.statusMessage} ${styles[submitStatus.type]}`} role="status">
                {submitStatus.message}
              </div>
            )}

            <CForm onSubmit={handleSubmit} noValidate>
              <div className={styles.row}>
                <div className={styles.formGroup}>
                  <label className={styles.formLabel} htmlFor="c-first">First name *</label>
                  <CFormInput id="c-first" type="text" name="firstName" value={formData.firstName} onChange={handleChange} placeholder="Juan" className={styles.formInput} disabled={isSubmitting} />
                </div>
                <div className={styles.formGroup}>
                  <label className={styles.formLabel} htmlFor="c-last">Last name *</label>
                  <CFormInput id="c-last" type="text" name="lastName" value={formData.lastName} onChange={handleChange} placeholder="Dela Cruz" className={styles.formInput} disabled={isSubmitting} />
                </div>
              </div>

              <div className={styles.row}>
                <div className={styles.formGroup}>
                  <label className={styles.formLabel} htmlFor="c-email">Email *</label>
                  <CFormInput id="c-email" type="email" name="email" value={formData.email} onChange={handleChange} placeholder="you@company.com" className={styles.formInput} disabled={isSubmitting} />
                </div>
                <div className={styles.formGroup}>
                  <label className={styles.formLabel} htmlFor="c-phone">Phone</label>
                  <CFormInput id="c-phone" type="tel" name="phone" value={formData.phone} onChange={handleChange} placeholder="Optional" className={styles.formInput} disabled={isSubmitting} />
                </div>
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel} htmlFor="c-option">Service *</label>
                <CFormSelect id="c-option" name="option" value={formData.option} onChange={handleChange} className={styles.formInput} options={options} disabled={isSubmitting} />
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel} htmlFor="c-message">Message *</label>
                <CFormTextarea id="c-message" name="message" value={formData.message} onChange={handleChange} placeholder="Tell me a little about your project..." rows={5} className={styles.formInput} disabled={isSubmitting} />
              </div>

              <button type="submit" className={styles.sendButton} disabled={isSubmitting}>
                <span>{isSubmitting ? 'Sending…' : 'Send message'}</span>
                {isSubmitting ? (
                  <span className={styles.spinner} aria-hidden="true" />
                ) : (
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                    <path d="M7 17L17 7M17 7H8M17 7V16" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                  </svg>
                )}
              </button>
            </CForm>
          </div>
        </div>
      </div>
    </CContainer>
  );
}

export default Contact;
