import React, { useEffect, useRef } from 'react';
import { CContainer } from '@coreui/react';
import SectionHeading from './ui/SectionHeading';
import styles from '../css/Experience.module.css';

// start / end are [year, month(1-12)] — period text and duration are derived from them
const experiences = [
  {
    id: 1,
    start: [2019, 1],
    end: [2026, 3],
    title: 'Sr. Front End Developer',
    company: 'Customer Benefits SVCS',
    description: 'Translating design concepts into interactive, functional and high-performing web applications.',
    current: true,
  },
  {
    id: 2,
    start: [2017, 12],
    end: [2018, 12],
    title: 'Web / Graphic Designer',
    company: 'Solar Systems Philippines Inc.',
    description: 'Created visually striking, user-friendly designs for websites and marketing assets.',
  },
  {
    id: 3,
    start: [2017, 9],
    end: [2017, 11],
    title: 'Jr. Front End Developer',
    company: 'Plane Mobile Biz Club',
    description: 'Improved the usability and visual appeal of web applications.',
  },
  {
    id: 4,
    start: [2017, 4],
    end: [2017, 8],
    title: 'Front End Developer',
    company: 'Mopro Philippines',
    description: 'Built responsive, visually appealing user interfaces.',
  },
];

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

const formatPeriod = ([sy, sm], [ey, em]) => `${MONTHS[sm - 1]} ${sy} — ${MONTHS[em - 1]} ${ey}`;

const formatYears = ([sy], [ey]) => (sy === ey ? `${sy}` : `${sy}–${String(ey).slice(2)}`);

// inclusive month count, e.g. Jan 2019 → Mar 2026 = 7 yrs 3 mos
const formatDuration = ([sy, sm], [ey, em]) => {
  const total = (ey - sy) * 12 + (em - sm) + 1;
  const y = Math.floor(total / 12);
  const m = total % 12;
  const parts = [];
  if (y) parts.push(`${y} yr${y > 1 ? 's' : ''}`);
  if (m) parts.push(`${m} mo${m > 1 ? 's' : ''}`);
  return parts.join(' ');
};

function Experience() {
  const timelineRef = useRef(null);

  // Draw the timeline line as the section scrolls through the viewport
  useEffect(() => {
    const el = timelineRef.current;
    if (!el) return undefined;
    let frame;

    const update = () => {
      frame = null;
      const r = el.getBoundingClientRect();
      const vh = window.innerHeight;
      const progress = Math.min(Math.max((vh * 0.6 - r.top) / r.height, 0), 1);
      el.style.setProperty('--line', progress.toFixed(3));
    };
    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(update);
    };

    update();
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    return () => {
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
      if (frame) cancelAnimationFrame(frame);
    };
  }, []);

  return (
    <CContainer>
      <SectionHeading
        index="03"
        eyebrow="Experience"
        title="Where I've"
        highlight="shipped work"
        subtitle="My professional journey and the skills I've picked up along the way."
      />

      <ol className={styles.timeline} ref={timelineRef}>
        <span className={styles.track} aria-hidden="true">
          <span className={styles.fill} />
        </span>

        {experiences.map((exp, i) => {
          const flip = i % 2 === 1;
          return (
            <li key={exp.id} className={`${styles.item} ${flip ? styles.flip : ''}`}>
              <div
                className={`reveal card-glass spot ${styles.card}`}
                data-anim={flip ? 'right' : 'left'}
                data-delay="1"
              >
                <div className={styles.cardHead}>
                  <span className={styles.period}>{formatPeriod(exp.start, exp.end)}</span>
                  {exp.current && <span className={styles.badge}>Latest</span>}
                </div>
                <h3 className={styles.role}>{exp.title}</h3>
                <p className={styles.company}>@ {exp.company}</p>
                <p className={styles.description}>{exp.description}</p>
              </div>

              <span className={`reveal ${styles.node} ${exp.current ? styles.nodeCurrent : ''}`} data-anim="zoom" aria-hidden="true" />

              {/* Opposite side: big year range + duration */}
              <div className={`reveal ${styles.side}`} data-anim={flip ? 'left' : 'right'} data-delay="2" aria-hidden="true">
                <span className={styles.sideIndex}>{String(i + 1).padStart(2, '0')} / {String(experiences.length).padStart(2, '0')}</span>
                <span className={styles.years}>{formatYears(exp.start, exp.end)}</span>
                <span className={styles.duration}>
                  <span className={styles.durationDot} />
                  {formatDuration(exp.start, exp.end)}
                </span>
              </div>
            </li>
          );
        })}
      </ol>
    </CContainer>
  );
}

export default Experience;
