import React, { useEffect, useRef, useState } from 'react';
import { CContainer } from '@coreui/react';
import { StarIcon } from '@heroicons/react/24/solid';
import SectionHeading from './ui/SectionHeading';
import styles from '../css/Clients.module.css';

const clientList = [
  {
    id: 1,
    name: 'Zephario Lantavon',
    role: 'Business Coordinator',
    quote: "The web app exceeded our expectations in every way. It's fast, user-friendly, and looks fantastic. Highly recommend!",
    imageSrc: `${process.env.PUBLIC_URL}/images/clients-01.png`,
  },
  {
    id: 2,
    name: 'Ryderen Mirkovian',
    role: 'Business Coordinator',
    quote: 'The web app development process was seamless, thanks to Christian. The final product is professional, reliable, and impressive.',
    imageSrc: `${process.env.PUBLIC_URL}/images/clients-02.png`,
  },
  {
    id: 3,
    name: 'Elyndra Virelsa',
    role: 'Business Coordinator',
    quote: 'Our new web app is a game-changer for our business. Christian delivered exactly what we needed and more.',
    imageSrc: `${process.env.PUBLIC_URL}/images/clients-03.png`,
  },
  {
    id: 4,
    name: 'Thaelina Dravose',
    role: 'Business Coordinator',
    quote: 'Exceptional work! The web app is intuitive and beautifully designed. Christian truly understood our vision and brought it to life.',
    imageSrc: `${process.env.PUBLIC_URL}/images/clients-04.png`,
  },
];

const COPIES = 3;        // render the list 3× so the loop never shows a gap
const SPEED = 38;        // px per second
const N = clientList.length;

function Clients() {
  const viewportRef = useRef(null);
  const trackRef = useRef(null);
  const ctrl = useRef({ offset: 0, target: null, paused: false, dragging: false, dragOrigin: 0, setW: 0, step: 0, jump: null });
  const [active, setActive] = useState(0);

  useEffect(() => {
    const viewport = viewportRef.current;
    const track = trackRef.current;
    if (!viewport || !track) return undefined;
    const c = ctrl.current;
    const cards = Array.from(track.children);
    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    let raf;
    let last = performance.now();
    let lastActive = -1;

    // width of ONE copy of the list (distance between card 0 and card N)
    const measure = () => {
      c.setW = cards[N].offsetLeft - cards[0].offsetLeft;
      c.step = cards[1].offsetLeft - cards[0].offsetLeft;
    };
    measure();

    // jump so testimonial i sits in the centre
    c.jump = (i) => {
      const vw = viewport.clientWidth;
      const card = cards[N + i];
      // position of card centre inside the track, minus centre of viewport
      let goal = card.offsetLeft + card.offsetWidth / 2 - vw / 2 - c.setW;
      // pick the nearest equivalent loop position so it never spins far
      while (goal - c.offset > c.setW / 2) goal -= c.setW;
      while (c.offset - goal > c.setW / 2) goal += c.setW;
      c.target = goal;
    };

    const frame = (now) => {
      const dt = Math.min((now - last) / 1000, 0.05);
      last = now;

      if (c.target !== null) {
        // ease toward the requested card
        c.offset += (c.target - c.offset) * Math.min(1, dt * 6);
        if (Math.abs(c.target - c.offset) < 0.5) {
          c.offset = c.target;
          c.target = null;
        }
      } else if (!c.paused && !c.dragging && !reduce) {
        c.offset += SPEED * dt;
      }

      // keep offset inside one loop length — shift any target / drag origin by the
      // same amount so jumps and drags don't snap when the loop wraps
      if (c.setW) {
        const wrapped = ((c.offset % c.setW) + c.setW) % c.setW;
        const delta = wrapped - c.offset;
        if (delta) {
          c.offset = wrapped;
          if (c.target !== null) c.target += delta;
          c.dragOrigin += delta;
        }
      }

      track.style.transform = `translate3d(${-(c.offset + c.setW)}px,0,0)`;

      // focus: 1 at the viewport centre → 0 one card-width away
      const vw = viewport.clientWidth;
      const centre = vw / 2 + c.offset + c.setW;
      let best = 0;
      let bestF = -1;
      cards.forEach((el, i) => {
        const mid = el.offsetLeft + el.offsetWidth / 2;
        const f = Math.max(0, 1 - Math.abs(mid - centre) / (el.offsetWidth * 1.05));
        el.style.setProperty('--f', f.toFixed(3));
        if (f > bestF) { bestF = f; best = i % N; }
      });
      if (best !== lastActive) {
        lastActive = best;
        setActive(best);
      }

      raf = requestAnimationFrame(frame);
    };
    raf = requestAnimationFrame(frame);

    // ---- interactions ----
    const onEnter = () => { c.paused = true; };
    const onLeave = () => { c.paused = false; };

    let startX = 0;
    c.dragOrigin = 0;
    const onDown = (e) => {
      c.dragging = true;
      c.target = null;
      startX = e.clientX;
      c.dragOrigin = c.offset;
      viewport.setPointerCapture?.(e.pointerId);
      viewport.classList.add(styles.grabbing);
    };
    const onMove = (e) => {
      if (!c.dragging) return;
      c.offset = c.dragOrigin - (e.clientX - startX);
    };
    const onUp = () => {
      if (!c.dragging) return;
      c.dragging = false;
      viewport.classList.remove(styles.grabbing);
      // settle on the nearest card
      c.jump(lastActive < 0 ? 0 : lastActive);
    };

    viewport.addEventListener('pointerenter', onEnter);
    viewport.addEventListener('pointerleave', onLeave);
    viewport.addEventListener('pointerdown', onDown);
    viewport.addEventListener('pointermove', onMove);
    viewport.addEventListener('pointerup', onUp);
    viewport.addEventListener('pointercancel', onUp);
    window.addEventListener('resize', measure);

    return () => {
      cancelAnimationFrame(raf);
      viewport.removeEventListener('pointerenter', onEnter);
      viewport.removeEventListener('pointerleave', onLeave);
      viewport.removeEventListener('pointerdown', onDown);
      viewport.removeEventListener('pointermove', onMove);
      viewport.removeEventListener('pointerup', onUp);
      viewport.removeEventListener('pointercancel', onUp);
      window.removeEventListener('resize', measure);
    };
  }, []);

  const go = (i) => ctrl.current.jump?.(((i % N) + N) % N);

  const looped = Array.from({ length: COPIES }, (_, copy) =>
    clientList.map((client) => ({ ...client, key: `${copy}-${client.id}`, clone: copy !== 1 }))
  ).flat();

  return (
    <CContainer>
      <SectionHeading
        index="05"
        eyebrow="Testimonials"
        title="Kind words from"
        highlight="clients"
        subtitle="A diverse range of businesses and individuals I've had the pleasure of working with."
      >
        <div className={styles.navigation}>
          <button type="button" className={styles.navBtn} onClick={() => go(active - 1)} aria-label="Previous testimonial">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none"><path d="M15 18L9 12L15 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>
          </button>
          <button type="button" className={styles.navBtn} onClick={() => go(active + 1)} aria-label="Next testimonial">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none"><path d="M9 18L15 12L9 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>
          </button>
        </div>
      </SectionHeading>

      <div className={`reveal ${styles.viewport}`} data-delay="2" ref={viewportRef}>
        <div className={styles.track} ref={trackRef}>
          {looped.map((client) => (
            <figure
              key={client.key}
              className={`card-glass spot ${styles.card}`}
              aria-hidden={client.clone ? 'true' : undefined}
            >
              <div className={styles.top}>
                <div className={styles.stars} aria-label="5 out of 5 stars">
                  {[0, 1, 2, 3, 4].map((s) => <StarIcon key={s} />)}
                </div>
                <span className={styles.quoteMark} aria-hidden="true">”</span>
              </div>

              <blockquote className={styles.quote}>{client.quote}</blockquote>

              <figcaption className={styles.person}>
                <img
                  src={client.imageSrc}
                  alt={client.clone ? '' : client.name}
                  className={styles.avatar}
                  width={48}
                  height={48}
                  draggable={false}
                  onError={(e) => {
                    e.target.src = `https://ui-avatars.com/api/?name=${encodeURIComponent(client.name)}&background=22d3ee&color=07090d&rounded=true&size=96`;
                  }}
                />
                <div>
                  <p className={styles.name}>{client.name}</p>
                  <p className={styles.role}>{client.role}</p>
                </div>
              </figcaption>
            </figure>
          ))}
        </div>
      </div>

      <div className={styles.dots} role="tablist" aria-label="Choose testimonial">
        {clientList.map((client, i) => (
          <button
            key={client.id}
            type="button"
            role="tab"
            aria-selected={active === i}
            aria-label={`Testimonial from ${client.name}`}
            className={`${styles.dot} ${active === i ? styles.dotActive : ''}`}
            onClick={() => go(i)}
          />
        ))}
      </div>
    </CContainer>
  );
}

export default Clients;
