const scenes = [SceneCode, SceneUX, SceneBrand, SceneApp];

/* ---------------- Keyboard (real layout, backlit on boot) ---------------- */

const k = (label, w = 1) => ({ label, w });
const chars = (s) => s.split(' ').map((c) => k(c));

const KEY_ROWS = [
  { fn: true, keys: [k('esc', 1.5), ...Array.from({ length: 12 }, (_, i) => k(`F${i + 1}`)), k('', 1)] },
  { keys: [...chars('` 1 2 3 4 5 6 7 8 9 0 - ='), k('delete', 1.5)] },
  { keys: [k('tab', 1.5), ...chars('Q W E R T Y U I O P [ ]'), k('\\')] },
  { keys: [k('caps', 1.8), ...chars("A S D F G H J K L ; '"), k('return', 1.8)] },
  { keys: [k('shift', 2.35), ...chars('Z X C V B N M , . /'), k('shift', 2.35)] },
  { keys: [k('fn'), k('ctrl'), k('opt'), k('cmd', 1.25), k('', 5.1), k('cmd', 1.25), k('opt'), k('◀'), k('arrows'), k('▶')] },
];

const Keyboard = React.memo(function Keyboard() {
  return (
    <div className={styles.keyboard}>
      {KEY_ROWS.map((row, r) => (
        <div key={r} className={`${styles.keyRow} ${row.fn ? styles.fnRow : ''}`}>
          {row.keys.map((key, i) =>
            key.label === 'arrows' ? (
              <div key={i} className={styles.arrowStack}>
                <span className={styles.key}><em>▲</em></span>
                <span className={styles.key}><em>▼</em></span>
              </div>
            ) : (
              <span key={i} className={styles.key} style={{ flexGrow: key.w }}>
                <em className={key.label.length > 1 ? styles.small : ''}>{key.label}</em>
              </span>
            )
          )}
        </div>
      ))}
    </div>
  );
});

/* ---------------- Main component ---------------- */

function LaptopShowcase() {
  const wrapRef = useRef(null);
  const [active, setActive] = useState(-1);

  useEffect(() => {
    const el = wrapRef.current;
    if (!el) return undefined;
    let frame = null;
    let last = -2;

    const update = () => {
      frame = null;
      const rect = el.getBoundingClientRect();
      const total = rect.height - window.innerHeight;
      const p = clamp(-rect.top / total);

      const open = ease(range(p, 0.04, 0.32));
      const boot = range(p, 0.3, 0.38);
      const sp = range(p, 0.38, 0.98);

      el.style.setProperty('--p', p.toFixed(4));
      el.style.setProperty('--open', open.toFixed(4));
      el.style.setProperty('--boot', boot.toFixed(4));
      el.style.setProperty('--intro', (1 - range(p, 0.02, 0.14)).toFixed(4));
      el.style.setProperty('--sp', sp.toFixed(4));

      const idx = p < 0.38 ? -1 : Math.min(featured.length - 1, Math.floor(sp * featured.length));
      if (idx !== last) {
        last = idx;
        setActive(idx);
      }
    };

    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(update);
    };

    update();
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    return () => {
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
      if (frame) cancelAnimationFrame(frame);
    };
  }, []);

  const current = featured[Math.max(active, 0)];

  return (
    <div className={styles.wrap} ref={wrapRef}>
      <div className={styles.stage}>
        <div className="grid-bg" aria-hidden="true" />
        <div className={styles.halo} aria-hidden="true" />

        {/* Intro copy — fades away as the lid opens */}
        <div className={styles.intro}>
          <p className={styles.eyebrow}>{'// what I build'}</p>
          <h2 className={styles.introTitle}>
            Let me open up <span className="gradient-text">my workspace.</span>
          </h2>
          <p className={styles.scrollHint}>
            <span className={styles.mouse}><span /></span>
            Scroll to open
          </p>
        </div>

        {/* 3D laptop */}
        <div className={styles.scene} aria-hidden="true">
          <div className={styles.laptop}>
            <div className={styles.lid}>
              {/* physical thickness: back panel sits behind the screen, edges close the gap */}
              <div className={styles.lidBack}>
                <svg viewBox="0 0 48 48" className={styles.lidLogo}>
                  <defs>
                    <linearGradient id="lidLogoGrad" x1="0" y1="0" x2="1" y2="1">
                      <stop stopColor="#f4f7fb" />
                      <stop offset=".5" stopColor="#8d96a6" />
                      <stop offset="1" stopColor="#dfe5ee" />
                    </linearGradient>
                  </defs>
                  <path d="M20 16 A10 10 0 1 0 20 32 M25 16 L30 32 L35 16" fill="none" stroke="url(#lidLogoGrad)" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              </div>
              <div className={styles.lidEdgeTop} />
              <div className={styles.lidEdgeLeft} />
              <div className={styles.lidEdgeRight} />

              <div className={styles.screenFace}>
                <span className={styles.camera}><i /></span>
                <div className={styles.glass} />
                <div className={styles.display}>
                  <div className={styles.screenGlare} />
                  <div className={styles.screenContent}>
                    <div className={styles.topbar}>
                      <span className={styles.dots}><i /><i /><i /></span>
                      <span className={styles.url}>
                        <svg viewBox="0 0 16 16" width="10" height="10"><path d="M5 7V5a3 3 0 016 0v2M4 7h8v6H4z" fill="none" stroke="currentColor" strokeWidth="1.4" /></svg>
                        {active < 0 ? 'christian.dev' : current.url}
                      </span>
                      <span className={styles.topbarRight} />
                    </div>

                    <div className={styles.scenes}>
                      <div className={`${styles.boot} ${active < 0 ? styles.on : ''}`}>
                        <span className={styles.bootLogo}>CV</span>
                        <span className={styles.bootBar}><i /></span>
                      </div>
                      {scenes.map((Scene, i) => (
                        <div key={i} className={`${styles.sceneSlot} ${active === i ? styles.on : ''} ${active > i ? styles.past : ''}`}>
                          <Scene />
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className={styles.base}>
              <div className={styles.lightSpill} />
              <div className={styles.hinge} />
              <div className={`${styles.speaker} ${styles.speakerL}`} />
              <div className={`${styles.speaker} ${styles.speakerR}`} />
              <Keyboard />
              <div className={styles.trackpad} />
              <div className={styles.lip} />
              <div className={styles.sideL} />
              <div className={styles.sideR} />
            </div>
          </div>
          <div className={styles.shadow} />
          <div className={styles.contactShadow} />
        </div>

        {/* Caption for the active featured service */}
        <div className={`${styles.caption} ${active >= 0 ? styles.captionOn : ''}`}>
          <div className={styles.captionHead}>
            <span className={styles.captionIcon} key={active}>
              <ServiceIcon name={current.icon} size={30} className="animate" />
            </span>
            <span className={styles.captionMeta}>
              Featured service · {String(Math.max(active, 0) + 1).padStart(2, '0')} / {String(featured.length).padStart(2, '0')}
            </span>
          </div>
          <h3 className={styles.captionTitle} key={`t${active}`}>{current.title}</h3>
          <p className={styles.captionText} key={`p${active}`}>{current.text}</p>
          <div className={styles.rail}>
            {featured.map((f, i) => (
              <span key={f.title} style={{ '--fill': `clamp(0, calc(var(--sp) * ${featured.length} - ${i}), 1)` }} />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export default LaptopShowcase;
