import React from 'react';
import SplitWords from './SplitWords';
import styles from '../../css/SectionHeading.module.css';

/**
 * Consistent section header:  // 01 — eyebrow
 *                              Big headline (word-by-word reveal)
 *                              Muted subtitle
 */
function SectionHeading({ index, eyebrow, title, highlight, subtitle, align = 'left', children }) {
  return (
    <div className={`${styles.heading} ${align === 'center' ? styles.center : ''}`}>
      <div className={`${styles.textCol}`}>
        <p className={`reveal ${styles.eyebrow}`}>
          <span className={styles.index}>{index}</span>
          <span className={styles.line} />
          {eyebrow}
        </p>
        <h2 className={`reveal ${styles.title}`} data-delay="1">
          <SplitWords text={title} />
          {highlight && (
            <>
              {' '}
              <SplitWords text={highlight} start={title.split(' ').length * 0.06} className="gradient-text" />
            </>
          )}
        </h2>
        {subtitle && (
          <p className={`reveal ${styles.subtitle}`} data-delay="2">
            {subtitle}
          </p>
        )}
      </div>
      {children && (
        <div className={`reveal ${styles.aside}`} data-delay="3">
          {children}
        </div>
      )}
    </div>
  );
}

export default SectionHeading;
