import React, { useEffect, useRef, useState } from 'react';
import { startNeonDrift } from './phone/neonDrift';
import styles from '../css/PhoneShowcase.module.css';

/*
 * Scroll-driven mobile showcase.
 *  0.00 – 0.24  phone spins in from its back (camera module) to the front
 *  0.18 – 0.26  screen powers on → lock screen
 *  0.36 – 0.44  phone rotates to landscape → live mini-game ("Neon Drift")
 *  0.66 – 0.74  back to portrait → mobile app
 */

const clamp = (v, a = 0, b = 1) => Math.min(Math.max(v, a), b);
const range = (p, a, b) => clamp((p - a) / (b - a));
const ease = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);

const LAYERS = 14; // stacked rounded slabs = the titanium frame

const captions = {
  lock: {
    eyebrow: '// mobile',
    title: ['Games & apps that', 'feel native.'],
    text: 'From the first tap to the last frame, I design and build mobile experiences people want to keep in their pocket.',
    chips: ['iOS', 'Android', 'Cross-platform'],
  },
  game: {
    eyebrow: '// 01 — mobile games',
    title: ['Games with', 'game feel.'],
    text: 'Tight game loops, juicy hit feedback, particle effects and touch controls tuned for thumbs — running smooth at 60fps.',
    chips: ['Game loops', 'Particle FX', 'Touch controls', 'Canvas / WebGL'],
  },
  app: {
    eyebrow: '// 02 — mobile apps',
    title: ['Apps that feel', 'effortless.'],
    text: 'Pixel-perfect interfaces with fluid motion, clean architecture and real-world data — designed and built end to end.',
    chips: ['UI/UX design', 'Fluid animation', 'API integration', 'Store-ready'],
  },
};

/* ---------------- Screens ---------------- */

