// Projects.jsx - Contentful projects with category filter + pagination
import React, { useState, useEffect, useLayoutEffect, useRef } from 'react';
import { CContainer } from '@coreui/react';
import { useNavigate } from 'react-router-dom';
import { createClient } from 'contentful';
import SectionHeading from './ui/SectionHeading';
import styles from '../css/Project.module.css';

// Contentful client setup
const client = createClient({
  space: '7wddt967mgfr',
  accessToken: 'HDc3S_flilPqMp3DMm0LTOMpUWIhlDnLdjeTn8nyekY',
});

async function fetchProjects() {
  const entries = [];
  while (true) {
    const { items, total } = await client.getEntries({
      content_type: 'cvProjects',
      order: '-sys.createdAt,sys.id',
      limit: 100,
      skip: entries.length,
    });
    entries.push(...items);
    if (entries.length >= total) return entries;
    if (!items.length) throw new Error('Contentful returned an empty page of projects.');
  }
}

// Helper function to extract plain text from Contentful rich text
const extractDescription = (richText) => {
  if (!richText) return '';
  if (typeof richText === 'string') return richText;

  const extractText = (node) => {
    if (node.nodeType === 'text') return node.value || '';
    if (node.content) {
      const text = node.content.map(extractText).join('');
      // every block (paragraph, heading, list item…) ends with a space so
      // "Seat Cushion Funnel" + "Melara is…" doesn't become "FunnelMelara is…"
      return text && node.nodeType !== 'hyperlink' ? `${text} ` : text;
    }
    return '';
  };

  const full = (richText.content || []).map(extractText).join('').replace(/\s+/g, ' ').trim();
  return full;
};

// cut at a word boundary
const truncateText = (text, length = 140) => {
  if (!text || text.length <= length) return text || '';
  const cut = text.slice(0, length);
  return `${cut.slice(0, cut.lastIndexOf(' ')).replace(/[,.;:–—-]+$/, '')}…`;
};

// drop a leading sentence that just repeats the title (common in Contentful entries)
const stripTitle = (text, title) => {
  if (!text || !title) return text;
  const t = title.trim().toLowerCase();
  return text.toLowerCase().startsWith(t) ? text.slice(t.length).replace(/^[\s:.,–—-]+/, '') : text;
};

const formatDate = (d) => {
  if (!d) return '';
  const date = new Date(d);
  return Number.isNaN(date.getTime()) ? '' : date.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
};

const PROJECTS_PER_PAGE = 6;

function Projects() {
  const navigate = useNavigate();
  const [activeIndex, setActiveIndex] = useState(0);
  const [projectLists, setProjectLists] = useState([]);
  const [filteredProjects, setFilteredProjects] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [categories, setCategories] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef(null);
  const gridRef = useRef(null);
  const pillsRef = useRef(null);
  const [pillStyle, setPillStyle] = useState({ opacity: 0 });

  // Reset page when category changes
  useEffect(() => {
    setCurrentPage(1);
  }, [activeIndex]);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    setIsLoading(true);

    fetchProjects()
      .then((entries) => {
        const projectData = entries.map((item) => {
          const imageUrl = item.fields.image?.[0]?.fields?.file?.url
            ? `https:${item.fields.image[0].fields.file.url}`
            : '';

          let projectCategories = [];
          if (Array.isArray(item.fields.categories)) {
            projectCategories = item.fields.categories;
          } else if (typeof item.fields.categories === 'string') {
            projectCategories = [item.fields.categories];
          }

          return {
            id: item.sys.id,
            title: item.fields.title || 'Untitled',
            description: extractDescription(item.fields.description),
            categories: projectCategories,
            imageUrl,
            date: item.fields.date || '',
          };
        });

        setProjectLists(projectData);
        setFilteredProjects(projectData);
        setCategories([...new Set(projectData.flatMap((p) => p.categories || []))]);
        setIsLoading(false);
      })
      .catch((error) => {
        console.error('Error fetching data:', error);
        setIsLoading(false);
      });
  }, []);

  const handleCatLinks = (index, category) => {
    setActiveIndex(index);
    setIsDropdownOpen(false);
    setFilteredProjects(
      index === 0 ? projectLists : projectLists.filter((p) => p.categories?.includes(category))
    );
  };

  const handleReadMore = (projectId) => navigate(`/project/${projectId}`);

  // Pagination logic
  const indexOfLastProject = currentPage * PROJECTS_PER_PAGE;
  const indexOfFirstProject = indexOfLastProject - PROJECTS_PER_PAGE;
  const currentProjects = filteredProjects.slice(indexOfFirstProject, indexOfLastProject);
  const totalPages = Math.ceil(filteredProjects.length / PROJECTS_PER_PAGE);

  const goToPage = (page) => {
    setCurrentPage(page);
    // keep the grid in view when it is above the fold
    const top = gridRef.current?.getBoundingClientRect().top;
    if (top !== undefined && top < 0) {
      gridRef.current.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  };

  const getPageNumbers = () => {
    if (totalPages <= 5) return Array.from({ length: totalPages }, (_, i) => i + 1);
    if (currentPage <= 3) return [1, 2, 3, 4, '...', totalPages];
    if (currentPage >= totalPages - 2) return [1, '...', totalPages - 3, totalPages - 2, totalPages - 1, totalPages];
    return [1, '...', currentPage - 1, currentPage, currentPage + 1, '...', totalPages];
  };

  const categoryList = ['All', ...categories];
  const currentCategory = categoryList[activeIndex];

  // slide the highlight pill under the active filter
  useLayoutEffect(() => {
    const place = () => {
      const btn = pillsRef.current?.querySelector(`[data-pill="${activeIndex}"]`);
      if (!btn || !btn.offsetWidth) return;
      setPillStyle({ width: btn.offsetWidth, transform: `translateX(${btn.offsetLeft}px)`, opacity: 1 });
    };
    place();
    window.addEventListener('resize', place);
    return () => window.removeEventListener('resize', place);
  }, [activeIndex, categories.length]);

  return (
    <CContainer>
      <SectionHeading
        index="02"
        eyebrow="Selected work"
        title="Recent"
        highlight="projects"
        subtitle="A collection of my latest work — highlighting the quality, craft and creativity I bring to every build."
      />

      {/* Category Filter - Desktop pills, Mobile dropdown */}
      <div className={`reveal ${styles.filterBar}`} data-delay="2">
        <ul className={styles.pills} role="tablist" ref={pillsRef}>
          <span className={styles.pillIndicator} style={pillStyle} aria-hidden="true" />
          {categoryList.map((category, index) => (
            <li key={category}>
              <button
                type="button"
                role="tab"
                data-pill={index}
                aria-selected={activeIndex === index}
                className={`${styles.pill} ${activeIndex === index ? styles.active : ''}`}
                onClick={() => handleCatLinks(index, category)}
              >
                {category}
              </button>
            </li>
          ))}
        </ul>

        <div className={styles.dropdown} ref={dropdownRef}>
          <button
            type="button"
            className={styles.dropdownButton}
            onClick={() => setIsDropdownOpen(!isDropdownOpen)}
            aria-expanded={isDropdownOpen}
          >
            <span><span className={styles.dropdownLabel}>Filter:</span> {currentCategory}</span>
            <svg className={`${styles.dropdownIcon} ${isDropdownOpen ? styles.rotated : ''}`} width="18" height="18" viewBox="0 0 24 24" fill="none">
              <path d="M6 9L12 15L18 9" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </button>

          {isDropdownOpen && (
            <ul className={styles.dropdownMenu}>
              {categoryList.map((category, index) => (
                <li key={category}>
                  <button
                    type="button"
                    className={`${styles.dropdownItem} ${activeIndex === index ? styles.dropdownActive : ''}`}
                    onClick={() => handleCatLinks(index, category)}
                  >
                    {category}
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>

        <span className={styles.count}>
          {String(filteredProjects.length).padStart(2, '0')} projects
        </span>
      </div>

      {isLoading ? (
        <div className={styles.grid}>
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className={styles.skeleton} />
          ))}
        </div>
      ) : filteredProjects.length === 0 ? (
        <div className={styles.empty}>No projects found in this category.</div>
      ) : (
        <>
          {/* key forces a fresh mount so cards re-animate on filter / page change */}
          <div className={styles.grid} ref={gridRef} key={`${activeIndex}-${currentPage}`}>
            {currentProjects.map((project, i) => {
              const number = String(indexOfFirstProject + i + 1).padStart(2, '0');
              const date = formatDate(project.date);
              const desc = truncateText(stripTitle(project.description, project.title), 120);
              const thumb = project.imageUrl ? `${project.imageUrl}?w=720&fm=webp&q=80` : '';

              return (
                <article
                  key={project.id}
                  className={`reveal card-glass spot ${styles.card}`}
                  data-delay={(i % 3) + 1}
                  onClick={() => handleReadMore(project.id)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      handleReadMore(project.id);
                    }
                  }}
                  role="link"
                  tabIndex={0}
                  aria-label={`${project.title} — view case study`}
                >
                  <div className={styles.imageContainer}>
                    {thumb && (
                      <img
                        src={thumb}
                        className={styles.image}
                        alt=""
                        loading="lazy"
                        decoding="async"
                        onError={(e) => {
                          // fall back to the original asset if image params aren't supported
                          if (e.currentTarget.src !== project.imageUrl) e.currentTarget.src = project.imageUrl;
                        }}
                      />
                    )}
                    <span className={styles.number} aria-hidden="true">{number}</span>
                    <span className={styles.hoverCta} aria-hidden="true">
                      View case study
                      <svg width="16" height="16" viewBox="0 0 24 24" fill="none">
                        <path d="M7 17L17 7M17 7H8M17 7V16" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                      </svg>
                    </span>
                  </div>

                  <div className={styles.info}>
                    <div className={styles.meta}>
                      {project.categories?.length > 0 && (
                        <span className={styles.category}>{project.categories[0]}</span>
                      )}
                      {date && <span className={styles.date}>{date}</span>}
                    </div>
                    <h3 className={styles.name}>{project.title}</h3>
                    {desc && <p className={styles.description}>{desc}</p>}
                    <span className={styles.arrow} aria-hidden="true">
                      <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                        <path d="M7 17L17 7M17 7H8M17 7V16" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                      </svg>
                    </span>
                  </div>
                </article>
              );
            })}
          </div>

          {totalPages > 1 && (
            <nav className={styles.pagination} aria-label="Projects pagination">
              <button
                type="button"
                onClick={() => goToPage(currentPage - 1)}
                disabled={currentPage === 1}
                className={styles.pageBtn}
                aria-label="Previous page"
              >
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                  <path d="M15 18L9 12L15 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              </button>

              {getPageNumbers().map((page, index) =>
                page === '...' ? (
                  <span key={`dots-${index}`} className={styles.dots}>…</span>
                ) : (
                  <button
                    type="button"
                    key={page}
                    onClick={() => goToPage(page)}
                    className={`${styles.pageNumber} ${currentPage === page ? styles.activePage : ''}`}
                    aria-current={currentPage === page ? 'page' : undefined}
                  >
                    {page}
                  </button>
                )
              )}

              <button
                type="button"
                onClick={() => goToPage(currentPage + 1)}
                disabled={currentPage === totalPages}
                className={styles.pageBtn}
                aria-label="Next page"
              >
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                  <path d="M9 18L15 12L9 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              </button>

              <span className={styles.pageInfo}>
                {indexOfFirstProject + 1}–{Math.min(indexOfLastProject, filteredProjects.length)} / {filteredProjects.length}
              </span>
            </nav>
          )}
        </>
      )}
    </CContainer>
  );
}

export default Projects;
