// Footer.jsx - route-aware navigation
import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { CContainer } from '@coreui/react';
import styles from '../css/Footer.module.css';

const navLinks = [
  { name: 'Services', id: 'services' },
  { name: 'Works', id: 'projects' },
  { name: 'Experience', id: 'experience' },
  { name: 'Skills', id: 'skills' },
  { name: 'Blog', id: 'news' },
  { name: 'Contact', id: 'contact' },
];

function Footer() {
  const currentYear = new Date().getFullYear();
  const navigate = useNavigate();
  const location = useLocation();
  const isHomePage = location.pathname === '/';

  const scrollToSection = (sectionId) => {
    const go = () => document.getElementById(sectionId)?.scrollIntoView({ behavior: 'smooth' });
    if (isHomePage) {
      go();
    } else {
      navigate('/');
      setTimeout(go, 100);
    }
  };

  return (
    <footer className={styles.footer}>
      <div className="grid-bg" aria-hidden="true" />
      <CContainer className={styles.inner}>
        <div className={styles.top}>
          <div className="reveal">
            <img
              src={`${process.env.PUBLIC_URL}/images/logo-white.png`}
              alt="Christian Villareal"
              width={150}
              height={48}
              className={styles.logo}
              onClick={() => scrollToSection('home')}
            />
            <p className={styles.tagline}>
              Front-end developer &amp; UI/UX designer crafting fast, clean and honest web experiences.
            </p>
          </div>

          <nav className={`reveal ${styles.nav}`} data-delay="1" aria-label="Footer">
            {navLinks.map((link) => (
              <button key={link.id} type="button" onClick={() => scrollToSection(link.id)} className={styles.navLink}>
                {link.name}
              </button>
            ))}
          </nav>
        </div>

        <p className={`reveal ${styles.bigText}`} data-anim="blur" aria-hidden="true">
          Christian Villareal
        </p>

        <div className={styles.bottom}>
          <span>© {currentYear} Christian Villareal. All rights reserved.</span>
          <span className={styles.built}>Built with React · Designed in Cebu</span>
          <button type="button" className={styles.toTop} onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}>
            Back to top
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M12 19V5M5 12l7-7 7 7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </button>
        </div>
      </CContainer>
    </footer>
  );
}

export default Footer;
