import React from 'react';

/**
 * Splits text into words wrapped in `.w` spans with staggered delays.
 * Put it inside an element with the `.reveal` class: when that element
 * gets `.in`, each word un-blurs and slides up one after another.
 */
function SplitWords({ text, start = 0, step = 0.06, className }) {
  const words = text.split(' ');
  return words.map((word, i) => (
    <React.Fragment key={`${word}-${i}`}>
      <span className={className ? `w ${className}` : 'w'} style={{ transitionDelay: `${start + i * step}s` }}>
        {word}
      </span>
      {i < words.length - 1 && ' '}
    </React.Fragment>
  ));
}

export default SplitWords;
