const levelFor = (p) => {
  if (p >= 95) return 'Expert';
  if (p >= 85) return 'Advanced';
  if (p >= 65) return 'Proficient';
  return 'Intermediate';
};

/* Ring gauge that fills when its card scrolls into view (.in) */
function Gauge({ value, size = 72, stroke = 6, big = false }) {
  const gid = `g${useId().replace(/:/g, '')}`;
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;

  return (
    <div className={`${styles.gauge} ${big ? styles.gaugeBig : ''}`} style={{ width: size, height: size }}>
      <svg viewBox={`0 0 ${size} ${size}`} width={size} height={size} aria-hidden="true">
        <defs>
          <linearGradient id={gid} x1="0" y1="0" x2="1" y2="1">
            <stop stopColor="#22d3ee" />
            <stop offset=".55" stopColor="#818cf8" />
            <stop offset="1" stopColor="#c084fc" />
          </linearGradient>
        </defs>
        <circle className={styles.gaugeTrack} cx={size / 2} cy={size / 2} r={r} strokeWidth={stroke} />
        <circle
          className={styles.gaugeFill}
          cx={size / 2}
          cy={size / 2}
          r={r}
          strokeWidth={stroke}
          stroke={`url(#${gid})`}
          strokeDasharray={c}
          style={{ '--c': c, '--off': c * (1 - value / 100) }}
          transform={`rotate(-90 ${size / 2} ${size / 2})`}
        />
      </svg>
      <span className={styles.gaugeValue}>
        <CountUp end={value} suffix="%" duration={1600} />
      </span>
    </div>
  );
}

