import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import CustomButton from './CustomButton';
import { ArrowUpRightIcon } from '@heroicons/react/24/solid';
import styles from '../css/Header.module.css';

const navItems = [
  { name: 'Home', id: 'home' },
  { name: 'Services', id: 'services' },
  { name: 'Projects', id: 'projects' },
  { name: 'Experience', id: 'experience' },
  { name: 'Clients', id: 'clients' },
  { name: 'Contact', id: 'contact' },
];

function Header() {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [activeSection, setActiveSection] = useState('home');
  const navigate = useNavigate();
  const location = useLocation();

  const isHomePage = location.pathname === '/';

  // Compact header once the page scrolls
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 24);
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  // Track which section is in view
  useEffect(() => {
    if (!isHomePage) {
      setActiveSection('');
      return undefined;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) setActiveSection(entry.target.id);
        });
      },
      { rootMargin: '-50% 0px -50% 0px', threshold: 0 }
    );

    navItems.forEach(({ id }) => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, [isHomePage]);

  // Scroll to section or navigate home first
  const scrollToSection = (sectionId) => {
    const go = () => {
      const section = document.getElementById(sectionId);
      if (section) section.scrollIntoView({ behavior: 'smooth' });
      setActiveSection(sectionId);
    };

    if (isHomePage) {
      go();
    } else {
      navigate('/');
      setTimeout(go, 100);
    }
    setIsOpen(false);
  };

  return (
    <header className={`${styles.header} ${scrolled ? styles.scrolled : ''}`}>
      <nav className={styles.nav} aria-label="Main">
        <button
          type="button"
          className={styles.brand}
          onClick={() => scrollToSection('home')}
          aria-label="Christian Villareal — back to top"
        >
          <img src={`${process.env.PUBLIC_URL}/images/logo-white.png`} alt="Christian Villareal" width={140} height={45} />
        </button>

        <ul className={`${styles.links} ${isOpen ? styles.open : ''}`}>
          {navItems.map((item, i) => (
            <li key={item.id} style={{ '--i': i }}>
              <button
                type="button"
                onClick={() => scrollToSection(item.id)}
                className={`${styles.link} ${activeSection === item.id ? styles.active : ''}`}
              >
                {item.name}
              </button>
            </li>
          ))}
          <li className={styles.mobileCta} style={{ '--i': navItems.length }}>
            <CustomButton text="Hire Me" Icon={ArrowUpRightIcon} onClick={() => scrollToSection('contact')} />
          </li>
        </ul>

        <div className={styles.cta}>
          <CustomButton text="Hire Me" Icon={ArrowUpRightIcon} onClick={() => scrollToSection('contact')} size="sm" />
        </div>

        <button
          type="button"
          className={`${styles.toggler} ${isOpen ? styles.togglerOpen : ''}`}
          onClick={() => setIsOpen((v) => !v)}
          aria-expanded={isOpen}
          aria-label="Toggle navigation"
        >
          <span />
          <span />
        </button>
      </nav>
    </header>
  );
}

export default Header;
