import { useEffect } from 'react';

/**
 * Global scroll-animation engine (React port of the seat cushion reveal system).
 *
 * - Any element with `.reveal` fades/slides in when it enters the viewport
 *   (adds `.in`). Use `data-delay="1..6"` to stagger and `data-anim` for variants.
 * - A MutationObserver picks up elements rendered later (Contentful data,
 *   pagination, route changes), so components never have to register themselves.
 * - Elements with `.spot` get --mx / --my CSS vars for the cursor spotlight.
 * - Updates --progress on <html> for the scroll progress bar.
 */
export default function useScrollReveal() {
  useEffect(() => {
    const seen = new WeakSet();

    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          const el = entry.target;
          el.classList.add('in');
          io.unobserve(el);
          // once the entrance is over, hover effects get snappy timing again
          setTimeout(() => el.classList.add('revealed'), 1600);
        });
      },
      { threshold: 0.12, rootMargin: '0px 0px -40px 0px' }
    );

    const scan = () => {
      document.querySelectorAll('.reveal:not(.in)').forEach((el) => {
        if (seen.has(el)) return;
        seen.add(el);
        io.observe(el);
      });
    };
    scan();

    let scheduled = false;
    const mo = new MutationObserver(() => {
      if (scheduled) return;
      scheduled = true;
      requestAnimationFrame(() => {
        scheduled = false;
        scan();
      });
    });
    mo.observe(document.body, { childList: true, subtree: true });

    // Cursor spotlight on cards
    const onPointerMove = (e) => {
      const card = e.target.closest && e.target.closest('.spot');
      if (!card) return;
      const r = card.getBoundingClientRect();
      card.style.setProperty('--mx', `${e.clientX - r.left}px`);
      card.style.setProperty('--my', `${e.clientY - r.top}px`);
    };
    document.addEventListener('pointermove', onPointerMove, { passive: true });

    // Safety net: after scrolling stops, reveal anything already scrolled past
    // (fast jumps can skip over elements without ever intersecting them)
    let settleTimer;
    const revealPassed = () => {
      const vh = window.innerHeight;
      const vw = window.innerWidth;
      document.querySelectorAll('.reveal:not(.in)').forEach((el) => {
        const r = el.getBoundingClientRect();
        if (r.top < vh && r.right > 0 && r.left < vw) {
          el.classList.add('in');
          io.unobserve(el);
          setTimeout(() => el.classList.add('revealed'), 1600);
        }
      });
    };

    // Scroll progress
    const root = document.documentElement;
    const onScroll = () => {
      const max = root.scrollHeight - window.innerHeight;
      root.style.setProperty('--progress', max > 0 ? (window.scrollY / max).toFixed(4) : 0);
      clearTimeout(settleTimer);
      settleTimer = setTimeout(revealPassed, 180);
    };
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);

    return () => {
      clearTimeout(settleTimer);
      io.disconnect();
      mo.disconnect();
      document.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
    };
  }, []);
}
