import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import SEO from './components/SEO';

//Import Core UI and Bootstrap
import '@coreui/coreui/dist/css/coreui.min.css';
import 'bootstrap/dist/css/bootstrap.min.css';

//Import Global Styles (after the frameworks so tokens win)
import './css/global.css';

//Import Components
import Header from './components/Header';
import TopFold from './components/TopFold';
import Services from './components/Services';
import Projects from './components/Projects';
import Experience from './components/Experience';
import Skills from './components/Skills';
import Clients from './components/Clients';
import News from './components/News';
import Contact from './components/Contact';
import Footer from './components/Footer';
import ProjectDetails from './components/ProjectDetails';
import LaptopShowcase from './components/LaptopShowcase';
import PhoneShowcase from './components/PhoneShowcase';
import useScrollReveal from './hooks/useScrollReveal';

const getBasename = () => {
  const publicUrl = process.env.PUBLIC_URL || '/';

  try {
    const pathname = new URL(publicUrl, window.location.origin).pathname;
    return pathname.replace(/\/$/, '') || '/';
  } catch {
    return publicUrl.replace(/\/$/, '') || '/';
  }
};

function App() {
  const basename = getBasename();
  useScrollReveal();

  return (
    <Router basename={basename}>
      <div className="scroll-progress" aria-hidden="true" />
      <Header />

      <main>
        <Routes>
          {/* Home Route */}
          <Route path="/" element={
            <>
              <SEO
                title="Christian Villareal | Frontend Developer & UI/UX Designer"
                description="Frontend Developer specializing in modern web apps. View my projects in web design, development, and UX/UI. Based in Cebu, Philippines."
                keywords="React developer, frontend portfolio, web developer, UI/UX designer, JavaScript, Philippines, Christian Villareal"
                url="/"
                type="website"
              />

              {/* Section ids match Header + Footer navigation */}
              <section id="home"><TopFold /></section>
              <section id="showcase" aria-label="Featured services showcase"><LaptopShowcase /></section>
              <section id="services" className="section"><Services /></section>
              <section id="mobile" aria-label="Mobile games and apps showcase"><PhoneShowcase /></section>
              <section id="projects" className="section"><Projects /></section>
              <section id="experience" className="section"><Experience /></section>
              <section id="skills" className="section"><Skills /></section>
              <section id="clients" className="section"><Clients /></section>
              <section id="news" className="section"><News /></section>
              <section id="contact" className="section"><Contact /></section>
            </>
          } />

          {/* Project Details Route */}
          <Route path="/project/:id" element={<ProjectDetails />} />
        </Routes>
      </main>

      <Footer />
    </Router>
  );
}

export default App;
