import React from 'react';
import PropTypes from 'prop-types';
import { ArrowRightIcon } from '@heroicons/react/24/solid';
import styles from '../css/CustomButton.module.css';

function CustomButton({ text, onClick, Icon = ArrowRightIcon, variant = 'primary', size = 'md', type = 'button' }) {
  return (
    <button
      type={type}
      onClick={onClick}
      className={`${styles.button} ${styles[variant]} ${size === 'sm' ? styles.sm : ''}`}
    >
      <span>{text}</span>
      {Icon && <Icon className={styles.icon} aria-hidden="true" />}
    </button>
  );
}

CustomButton.propTypes = {
  text: PropTypes.string.isRequired,
  onClick: PropTypes.func,
  Icon: PropTypes.elementType,
  variant: PropTypes.oneOf(['primary', 'ghost']),
  size: PropTypes.oneOf(['sm', 'md']),
  type: PropTypes.string,
};

export default CustomButton;
