/*
 * "Neon Drift" — a tiny original side-scrolling shooter rendered on <canvas>.
 *
 * Modes
 *  demo  – an AI pilot plays; a "TAP TO PLAY" prompt pulses
 *  play  – the ship follows your finger / mouse, auto-fires, enemies can hit you
 *  over  – game over screen with score + best; tap to play again
 *
 * startNeonDrift(canvas, { onMode }) → { stop(), exit() }
 */

const W = 720;
const H = 330;
const MAX_HP = 5;
const IDLE_PLAY_MS = 7000;   // no input while playing → back to demo
const IDLE_OVER_MS = 6000;   // sitting on game over → back to demo
const BEST_KEY = 'neonDriftBest';

const rand = (a, b) => a + Math.random() * (b - a);
const pick = (arr) => arr[(Math.random() * arr.length) | 0];
const clampN = (v, a, b) => Math.min(Math.max(v, a), b);

const COLORS = ['#22d3ee', '#818cf8', '#c084fc', '#f472b6', '#34d399'];

const readBest = () => {
  try { return Number(localStorage.getItem(BEST_KEY)) || 0; } catch { return 0; }
};
const writeBest = (v) => {
  try { localStorage.setItem(BEST_KEY, String(v)); } catch { /* storage unavailable */ }
};

export function startNeonDrift(canvas, { onMode } = {}) {
  const ctx = canvas.getContext('2d');
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = W * dpr;
  canvas.height = H * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  const stars = Array.from({ length: 70 }, () => ({ x: rand(0, W), y: rand(0, H), z: pick([1, 2, 3]) }));

  let mode = 'demo';
  const player = { x: 90, y: H / 2, vy: 0, hp: MAX_HP, inv: 0 };
  const target = { x: 90, y: H / 2 };
  let bullets = [];
  let enemies = [];
  let particles = [];
  let texts = [];
  let score = 0;
  let best = readBest();
  let newBest = false;
  let combo = 1;
  let level = 1;
  let spawnT = 0;
  let fireT = 0;
  let shake = 0;
  let flash = 0;
  let t = 0;
  let lastInput = performance.now();
  let last = performance.now();
  let raf;

  const setMode = (m) => {
    if (m === mode) return;
    mode = m;
    if (onMode) onMode(m);
  };

  const resetRun = () => {
    bullets = [];
    enemies = [];
    texts = [];
    score = 0;
    combo = 1;
    level = 1;
    spawnT = 0.6;
    newBest = false;
    player.hp = MAX_HP;
    player.inv = 1.2;
  };

  /* ---------------- input ---------------- */

  // map a pointer position on the (3D-transformed) canvas into game space
  const toGame = (e) => {
    const r = canvas.getBoundingClientRect();
    if (!r.width || !r.height) return null;
    return {
      x: ((e.clientX - r.left) / r.width) * W,
      y: ((e.clientY - r.top) / r.height) * H,
    };
  };

  const steer = (e) => {
    const p = toGame(e);
    if (!p) return;
    target.x = clampN(p.x + 40, 40, W * 0.6); // keep the ship slightly ahead of the finger
    target.y = clampN(p.y, 24, H - 24);
  };

  const onDown = (e) => {
    e.preventDefault();
    lastInput = performance.now();
    if (canvas.setPointerCapture) {
      try { canvas.setPointerCapture(e.pointerId); } catch { /* ignore */ }
    }
    if (mode !== 'play') {
      resetRun();
      setMode('play');
    }
    steer(e);
  };

  const onMove = (e) => {
    if (mode !== 'play') return;
    // mouse steers on hover; touch / pen only while pressed
    if (e.pointerType !== 'mouse' && e.buttons === 0) return;
    lastInput = performance.now();
    steer(e);
  };

  // a still mouse / finger on the screen still counts as playing
  let inside = false;
  const onEnter = () => { inside = true; };
  const onLeave = () => {
    inside = false;
    lastInput = performance.now();
  };

  canvas.addEventListener('pointerdown', onDown);
  canvas.addEventListener('pointermove', onMove);
  canvas.addEventListener('pointerenter', onEnter);
  canvas.addEventListener('pointerleave', onLeave);

  /* ---------------- world ---------------- */

  const spawnEnemy = () => {
    const r = rand(11, 17);
    const y = rand(40, H - 40);
    enemies.push({
      x: W + 30,
      y,
      baseY: y,
      r,
      hp: r > 15 ? 2 : 1,
      speed: rand(110, 170) + level * 10,
      phase: rand(0, Math.PI * 2),
      amp: rand(10, 40),
      color: pick(COLORS),
      sides: pick([4, 6, 3]),
      rot: rand(0, Math.PI),
    });
  };

  const explode = (x, y, color, n = 22) => {
    for (let i = 0; i < n; i += 1) {
      const a = rand(0, Math.PI * 2);
      const s = rand(60, 320);
      particles.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, life: rand(0.35, 0.8), max: 0.8, color, size: rand(1.5, 3.5) });
    }
    particles.push({ ring: true, x, y, r: 4, life: 0.4, max: 0.4, color });
  };

  const polygon = (x, y, r, sides, rot) => {
    ctx.beginPath();
    for (let i = 0; i < sides; i += 1) {
      const a = rot + (i / sides) * Math.PI * 2;
      if (i === 0) ctx.moveTo(x + Math.cos(a) * r, y + Math.sin(a) * r);
      else ctx.lineTo(x + Math.cos(a) * r, y + Math.sin(a) * r);
    }
    ctx.closePath();
  };

  const gameOver = () => {
    explode(player.x, player.y, '#22d3ee', 40);
    explode(player.x, player.y, '#f472b6', 30);
    shake = 14;
    flash = 0.4;
    if (score > best) {
      best = score;
      newBest = true;
      writeBest(best);
    }
    lastInput = performance.now();
    setMode('over');
  };

  const update = (dt, now) => {
    t += dt;
    level = 1 + Math.floor(score / 2500);

    // idle timeouts
    if (mode === 'play' && !inside && now - lastInput > IDLE_PLAY_MS) setMode('demo');
    if (mode === 'over' && now - lastInput > IDLE_OVER_MS) {
      resetRun();
      setMode('demo');
    }

    stars.forEach((s) => {
      s.x -= s.z * 40 * dt * (1 + level * 0.1);
      if (s.x < 0) { s.x = W; s.y = rand(0, H); }
    });

    spawnT -= dt;
    if (spawnT <= 0) {
      spawnEnemy();
      spawnT = Math.max(0.35, 0.85 - level * 0.06) * rand(0.7, 1.2);
    }

    // ---- pilot ----
    if (mode === 'demo') {
      const next = enemies.filter((e) => e.x > player.x + 30).sort((a, b) => a.x - b.x)[0];
      const goalY = next ? next.y : H / 2 + Math.sin(t * 1.3) * 60;
      player.vy += (goalY - player.y) * 9 * dt;
      player.vy *= 0.86;
      player.y = clampN(player.y + player.vy * dt * 8, 24, H - 24);
      player.x += (90 - player.x) * Math.min(1, dt * 3);
    } else if (mode === 'play') {
      const k = Math.min(1, dt * 12);
      const prevY = player.y;
      player.x += (target.x - player.x) * k;
      player.y += (target.y - player.y) * k;
      player.vy = (player.y - prevY) / Math.max(dt, 0.001) / 8;
    }

    // ---- fire (not while dead) ----
    if (mode !== 'over') {
      fireT -= dt;
      if (fireT <= 0) {
        bullets.push({ x: player.x + 22, y: player.y - 5 }, { x: player.x + 22, y: player.y + 5 });
        fireT = mode === 'play' ? 0.12 : 0.14;
      }
    }
    bullets.forEach((b) => { b.x += 720 * dt; });
    bullets = bullets.filter((b) => b.x < W + 20);

    enemies.forEach((e) => {
      e.x -= e.speed * dt;
      e.y = e.baseY + Math.sin(t * 2 + e.phase) * e.amp;
      e.rot += dt * 2;
    });

    // ---- bullets vs enemies ----
    enemies.forEach((e) => {
      bullets.forEach((b) => {
        if (b.dead || e.dead) return;
        if ((b.x - e.x) ** 2 + (b.y - e.y) ** 2 < (e.r + 4) ** 2) {
          b.dead = true;
          e.hp -= 1;
          e.hit = 0.08;
          if (e.hp <= 0) {
            e.dead = true;
            const pts = 100 * combo;
            if (mode !== 'over') score += pts;
            combo = Math.min(combo + 1, 9);
            shake = Math.max(shake, 5);
            explode(e.x, e.y, e.color);
            texts.push({ x: e.x, y: e.y - 10, txt: `+${pts}`, life: 0.8, color: e.color });
          }
        }
      });
      if (!e.dead && e.x < -30) {
        e.dead = true;
        combo = 1;
      }
    });

    // ---- enemies vs player (only when you're playing) ----
    player.inv = Math.max(0, player.inv - dt);
    if (mode === 'play' && player.inv === 0) {
      enemies.forEach((e) => {
        if (e.dead) return;
        if ((e.x - player.x) ** 2 + (e.y - player.y) ** 2 < (e.r + 11) ** 2) {
          e.dead = true;
          explode(e.x, e.y, e.color, 16);
          player.hp -= 1;
          player.inv = 1.2;
          combo = 1;
          shake = 10;
          flash = 0.25;
          if (player.hp <= 0) gameOver();
        }
      });
    }

    bullets = bullets.filter((b) => !b.dead);
    enemies = enemies.filter((e) => !e.dead);
    enemies.forEach((e) => { if (e.hit) e.hit = Math.max(0, e.hit - dt); });

    particles.forEach((p) => {
      p.life -= dt;
      if (p.ring) { p.r += 220 * dt; return; }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vx *= 0.94;
      p.vy *= 0.94;
    });
    particles = particles.filter((p) => p.life > 0);

    texts.forEach((x) => { x.life -= dt; x.y -= 30 * dt; });
    texts = texts.filter((x) => x.life > 0);

    shake = Math.max(0, shake - dt * 30);
    flash = Math.max(0, flash - dt);
  };

  /* ---------------- render ---------------- */

  const centerText = (txt, y, font, color) => {
    ctx.font = font;
    ctx.fillStyle = color;
    ctx.fillText(txt, (W - ctx.measureText(txt).width) / 2, y);
  };

  const pill = (x, y, w, h) => {
    const r = h / 2;
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  };

  const drawShip = () => {
    if (mode === 'over') return;
    // blink while invulnerable
    if (player.inv > 0 && Math.floor(player.inv * 12) % 2 === 0) return;
    const tilt = clampN(player.vy * 0.02, -0.35, 0.35);
    ctx.save();
    ctx.translate(player.x, player.y);
    ctx.rotate(tilt);
    const flame = 14 + Math.sin(t * 40) * 5;
    const fg = ctx.createLinearGradient(-flame - 14, 0, -10, 0);
    fg.addColorStop(0, 'rgba(192,132,252,0)');
    fg.addColorStop(1, 'rgba(34,211,238,0.95)');
    ctx.fillStyle = fg;
    ctx.beginPath();
    ctx.moveTo(-10, -5);
    ctx.lineTo(-flame - 14, 0);
    ctx.lineTo(-10, 5);
    ctx.fill();
    ctx.shadowColor = mode === 'play' ? '#34d399' : '#22d3ee';
    ctx.shadowBlur = 18;
    ctx.fillStyle = '#e7f9ff';
    ctx.beginPath();
    ctx.moveTo(22, 0);
    ctx.lineTo(-12, -13);
    ctx.lineTo(-6, 0);
    ctx.lineTo(-12, 13);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = mode === 'play' ? '#34d399' : '#22d3ee';
    ctx.beginPath();
    ctx.ellipse(4, 0, 6, 3, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  };

  const draw = () => {
    ctx.save();
    if (shake) ctx.translate(rand(-shake, shake), rand(-shake, shake));

    const bg = ctx.createLinearGradient(0, 0, W, H);
    bg.addColorStop(0, '#070a16');
    bg.addColorStop(1, '#120a24');
    ctx.fillStyle = bg;
    ctx.fillRect(-20, -20, W + 40, H + 40);

    ctx.strokeStyle = 'rgba(129,140,248,0.12)';
    ctx.lineWidth = 1;
    const off = (t * 80) % 40;
    for (let x = -off; x < W; x += 40) {
      ctx.beginPath();
      ctx.moveTo(x, H);
      ctx.lineTo(W / 2 + (x - W / 2) * 0.3, H * 0.62);
      ctx.stroke();
    }

    stars.forEach((s) => {
      ctx.fillStyle = `rgba(200,220,255,${0.25 * s.z})`;
      ctx.fillRect(s.x, s.y, s.z * 1.6, s.z * 0.8);
    });

    ctx.globalCompositeOperation = 'lighter';

    bullets.forEach((b) => {
      ctx.strokeStyle = '#67e8f9';
      ctx.lineWidth = 2.5;
      ctx.shadowColor = '#22d3ee';
      ctx.shadowBlur = 10;
      ctx.beginPath();
      ctx.moveTo(b.x - 14, b.y);
      ctx.lineTo(b.x, b.y);
      ctx.stroke();
    });

    enemies.forEach((e) => {
      ctx.shadowColor = e.color;
      ctx.shadowBlur = 16;
      ctx.strokeStyle = e.hit ? '#fff' : e.color;
      ctx.lineWidth = 2.5;
      polygon(e.x, e.y, e.r, e.sides, e.rot);
      ctx.stroke();
      ctx.fillStyle = `${e.color}33`;
      ctx.fill();
      ctx.fillStyle = e.color;
      ctx.beginPath();
      ctx.arc(e.x, e.y, 2.5, 0, Math.PI * 2);
      ctx.fill();
    });

    ctx.shadowBlur = 0;
    particles.forEach((p) => {
      ctx.globalAlpha = p.life / p.max;
      if (p.ring) {
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.stroke();
      } else {
        ctx.fillStyle = p.color;
        ctx.fillRect(p.x, p.y, p.size, p.size);
      }
    });
    ctx.globalAlpha = 1;

    drawShip();

    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;

    ctx.font = '600 14px "JetBrains Mono", monospace';
    texts.forEach((x) => {
      ctx.globalAlpha = Math.min(1, x.life * 2);
      ctx.fillStyle = x.color;
      ctx.fillText(x.txt, x.x, x.y);
    });
    ctx.globalAlpha = 1;
    ctx.restore();

    // damage flash
    if (flash) {
      ctx.fillStyle = `rgba(244,114,182,${flash * 0.6})`;
      ctx.fillRect(0, 0, W, H);
    }

    // ---- HUD ----
    ctx.fillStyle = 'rgba(255,255,255,0.92)';
    ctx.font = '700 20px "Space Grotesk", sans-serif';
    ctx.fillText(String(score).padStart(6, '0'), 54, 34);
    ctx.font = '500 11px "JetBrains Mono", monospace';
    ctx.fillStyle = 'rgba(255,255,255,0.5)';
    ctx.fillText(mode === 'play' ? 'SCORE' : `BEST ${String(best).padStart(6, '0')}`, 54, 48);

    ctx.fillStyle = combo > 1 ? '#f472b6' : 'rgba(255,255,255,0.35)';
    ctx.font = '700 16px "Space Grotesk", sans-serif';
    ctx.fillText(`x${combo}`, 150, 34);

    ctx.fillStyle = 'rgba(255,255,255,0.5)';
    ctx.font = '500 11px "JetBrains Mono", monospace';
    ctx.fillText(`LVL ${level}`, W - 150, 30);
    for (let i = 0; i < MAX_HP; i += 1) {
      ctx.fillStyle = i < player.hp ? '#34d399' : 'rgba(255,255,255,0.15)';
      ctx.fillRect(W - 150 + i * 16, 38, 12, 5);
    }

    // ---- mode overlays ----
    if (mode === 'demo') {
      const pulse = 0.55 + Math.sin(t * 4) * 0.45;
      const w = 190;
      const h = 40;
      const x = (W - w) / 2;
      const y = H - 74;
      ctx.fillStyle = 'rgba(7,10,22,0.75)';
      pill(x, y, w, h);
      ctx.fill();
      ctx.strokeStyle = `rgba(34,211,238,${0.35 + pulse * 0.5})`;
      ctx.lineWidth = 2;
      ctx.stroke();
      centerText('TAP TO PLAY', y + 26, '700 16px "Space Grotesk", sans-serif', `rgba(255,255,255,${0.6 + pulse * 0.4})`);
    }

    if (mode === 'over') {
      ctx.fillStyle = 'rgba(5,7,14,0.62)';
      ctx.fillRect(0, 0, W, H);
      centerText('GAME OVER', H / 2 - 34, '700 40px "Space Grotesk", sans-serif', '#ffffff');
      centerText(`SCORE ${score}`, H / 2 + 2, '600 16px "JetBrains Mono", monospace', '#22d3ee');
      centerText(newBest ? '★ NEW BEST ★' : `BEST ${best}`, H / 2 + 26, '500 13px "JetBrains Mono", monospace', newBest ? '#fbbf24' : 'rgba(255,255,255,0.6)');
      const pulse = 0.5 + Math.sin(t * 4) * 0.5;
      centerText('TAP TO PLAY AGAIN', H / 2 + 66, '700 15px "Space Grotesk", sans-serif', `rgba(255,255,255,${0.5 + pulse * 0.5})`);
    }
  };

  const loop = (now) => {
    const dt = Math.min((now - last) / 1000, 1 / 30);
    last = now;
    update(dt, now);
    draw();
    raf = requestAnimationFrame(loop);
  };

  // pre-warm so the first frame already has action on screen
  for (let i = 0; i < 90; i += 1) update(1 / 60, performance.now());
  draw();
  raf = requestAnimationFrame(loop);

  return {
    stop() {
      cancelAnimationFrame(raf);
      canvas.removeEventListener('pointerdown', onDown);
      canvas.removeEventListener('pointermove', onMove);
      canvas.removeEventListener('pointerenter', onEnter);
      canvas.removeEventListener('pointerleave', onLeave);
    },
    exit() {
      resetRun();
      setMode('demo');
    },
  };
}
